public class CommonExceptionsDemo {
    public static void main(String[] args) {
        // 1. Defensive String Comparison
        String userRole = null;
        if ("ADMIN".equals(userRole)) {
            System.out.println("Admin access");
        } else {
            System.out.println("Safe comparison: No NPE with Yoda equals");
        }

        // 2. Safe Parsing
        String input = "  450 ";
        int parsed = parseOrDefault(input, 0);
        System.out.println("Parsed value: " + parsed);

        String badInput = "$120";
        int badParsed = parseOrDefault(badInput, -1);
        System.out.println("Bad input default: " + badParsed);
    }

    public static int parseOrDefault(String str, int defaultVal) {
        if (str == null) return defaultVal;
        try {
            return Integer.parseInt(str.trim());
        } catch (NumberFormatException e) {
            return defaultVal;
        }
    }
}

