public class ArrayLookup {
    public static String getElementSafe(String[] items, int index, String fallback) {
        if (items == null || index < 0 || index >= items.length) {
            return fallback;
        }
        return items[index];
    }

    public static void main(String[] args) {
        String[] fruits = {"Apple", "Banana", "Cherry"};
        System.out.println(getElementSafe(fruits, 1, "None"));
        System.out.println(getElementSafe(fruits, 5, "None"));
        System.out.println(getElementSafe(null, 0, "None"));
    }
}

