public class SanitizedSum {
    public static int sumTokens(String[] tokens) {
        int total = 0;
        if (tokens == null) return 0;
        for (String token : tokens) {
            if (token != null) {
                try {
                    total += Integer.parseInt(token.trim());
                } catch (NumberFormatException ignored) {
                }
            }
        }
        return total;
    }

    public static void main(String[] args) {
        String[] raw = {"10", "abc", null, "25", "  15 ", "9.5"};
        System.out.println("Total: " + sumTokens(raw));
    }
}

