practiceProblems.solution:
public class SafeSubstring {
    public static String safeSubstring(String str, int start, int end) {
        if (str == null) return "";
        int len = str.length();
        int s = Math.max(0, start);
        int e = Math.min(len, end);
        if (s >= e) return "";
        return str.substring(s, e);
    }

    public static void main(String[] args) {
        System.out.println(safeSubstring("Developer", 0, 4));
        System.out.println(safeSubstring("Developer", -2, 20));
        System.out.println(safeSubstring(null, 0, 5));
    }
}

